contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint64 before_number = c.number(); if (__ESBMC_reverted()) return;
        uint64 before_timestamp = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 before_basefee = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 before_hash = c.hash(); if (__ESBMC_reverted()) return;
        uint64 before_sequenceNumber = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 before_batcherHash = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 before_l1FeeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 before_l1FeeScalar = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.number() == before_number &&
            c.timestamp() == before_timestamp &&
            c.basefee() == before_basefee &&
            c.hash() == before_hash &&
            c.sequenceNumber() == before_sequenceNumber &&
            c.batcherHash() == before_batcherHash &&
            c.l1FeeOverhead() == before_l1FeeOverhead &&
            c.l1FeeScalar() == before_l1FeeScalar
        );
    }

    receive() external payable {}
}

